import os, json, numpy as np

BASE = 'storage/noesis/nmap'
SUMMARY = os.path.join(BASE, 'appendix_E_summary.json')
SCI_CMP = os.path.join(BASE, 'scientia_23_sets_compare.json')          # Eval 674
SCI_CX  = os.path.join(BASE, 'scientia_23_crossing_examples.json')     # Eval 674
SCI_SLK = os.path.join(BASE, 'scientia_23_crossing_slacks.json')       # Eval 679

def load_json(p):
    if not os.path.exists(p): return None
    try:
        with open(p,'r') as f: return json.load(f)
    except Exception:
        return None

def save_json(p, obj):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w') as f: json.dump(obj, f, indent=2)

def construct_packing():
    summary = load_json(SUMMARY) or {"version":"v2","notes":"Appendix E consolidated summary (sets-only)."}
    cmpd = load_json(SCI_CMP) or {}
    cxd  = load_json(SCI_CX)  or {}
    sld  = load_json(SCI_SLK) or {}

    # Counts
    motifs = cxd.get('crossing_examples_strict', []) + cxd.get('crossing_examples_inclusive', [])
    both_near = sum(1 for m in (sld.get('motifs', []) or []) if m.get('both_near_active@1e-8', False))

    summary['scientia_23'] = {
        "eval_compare": 674,
        "eval_boundary_correction": 676,
        "eval_slack_audit": 679,
        "files": cmpd.get('files', {}),
        "counts": cmpd.get('counts', {}),
        "jaccards": cmpd.get('jaccards', {}),
        "gate_v1_noesis": cmpd.get('gate_v1_noesis', {}),
        "crossing": {
            "motif_count": len(motifs),
            "strict_preview": cxd.get('crossing_examples_strict', [])[:3],
            "inclusive_preview": cxd.get('crossing_examples_inclusive', [])[:3]
        },
        "slack_audit": {
            "tol": sld.get('tol', 1e-8),
            "motifs_evaluated": len(sld.get('motifs', []) or []),
            "both_near_active_count": both_near,
            "json": SCI_SLK
        }
    }

    save_json(SUMMARY, summary)

    # Return valid pack (baseline with tiny shrink)
    SNAP_C = 'storage/noesis/latest_centers.txt'
    SNAP_R = 'storage/noesis/latest_radii.txt'
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(26,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(26,)
    else:
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float)
        r = np.full(26, 0.08, float)
    r = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r.astype(float)
